{"command":"python3 - <<'EOF'
import re
lines = open('/tmp/mac_job.log', encoding='utf-8', errors='replace').read().splitlines()
rows = []
in_table = False
for ln in lines:
    m = re.match(r'^\S+ (\d+)\s{2,}(\S.*)$', ln)
    if m:
        size, name = int(m.group(1)), m.group(2).strip()
        if name.startswith('Fa.app/') or name == 'TOTAL':
            rows.append((size, name))
# dedupe keeping order
seen = {}
for size, name in rows:
    seen[name] = size
print(len(seen), 'rows')
for name, size in sorted(seen.items()):
    print(size, name[:80])
EOF"}

